style.css:
@-moz-document domain("roblox.com") {
/* Hide the original "Roblox Premium" text */
  h2.premium-title {
    color: transparent !important;
    position: relative;
  }

  /* Replace with "Builder’s Club" in the exact position */
  h2.premium-title::after {
    content: "Builder’s Club";
    color: white !important; /* Match Roblox's text color */
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    text-align: left;  /* Align text to the left (no centering) */
    line-height: normal; /* Keep line height consistent */
  }
}
